//! Comparable map workloads for `perf-ahash`.
//!
//! These synthetic keys are generated by trusted test code. The measurements do
//! not establish the suitability of a hasher for attacker-controlled inputs.

use std::collections::HashMap;
use std::hash::BuildHasher;

/// Count owned string keys with the standard randomized hasher.
pub fn count_names_std(names: &[String]) -> HashMap<String, usize> {
    count_names(names)
}

/// Count the same string keys with a randomly initialized AHash state.
pub fn count_names_ahash(names: &[String]) -> HashMap<String, usize, ahash::RandomState> {
    count_names(names)
}

/// Count trusted string keys with FxHash; this is not an untrusted-input default.
pub fn count_names_fx(names: &[String]) -> rustc_hash::FxHashMap<String, usize> {
    count_names(names)
}

fn count_names<S: BuildHasher + Default>(names: &[String]) -> HashMap<String, usize, S> {
    let mut counts = HashMap::with_capacity_and_hasher(names.len(), S::default());
    for name in names {
        *counts.entry(name.clone()).or_insert(0) += 1;
    }
    counts
}

/// Build an integer-key map, replacing earlier values for duplicate keys.
pub fn build_nodes_std(nodes: &[(u32, String)]) -> HashMap<u32, String> {
    build_nodes(nodes)
}

/// Build the same map using AHash's randomly initialized state.
pub fn build_nodes_ahash(nodes: &[(u32, String)]) -> HashMap<u32, String, ahash::RandomState> {
    build_nodes(nodes)
}

/// Build the same map using FxHash, for synthetic trusted integer keys.
pub fn build_nodes_fx(nodes: &[(u32, String)]) -> rustc_hash::FxHashMap<u32, String> {
    build_nodes(nodes)
}

fn build_nodes<S: BuildHasher + Default>(nodes: &[(u32, String)]) -> HashMap<u32, String, S> {
    let mut map = HashMap::with_capacity_and_hasher(nodes.len(), S::default());
    map.extend(nodes.iter().cloned());
    map
}
